cssRules:
.tactile-card {
  background: #ffffff;
  border: 2px solid #000000;
  box-shadow: 4px 4px 0px #000000;
  border-radius: 4px;
  padding: 16px;
  transition: all 0.15s cubic-bezier(0.16, 1, 0.3, 1);
}
.tactile-card:hover {
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0px #000000;
}
.tactile-card:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0px #000000;
}
